Q: How to find the minimum value and count specific occurrences in a List of objects using basic loops in C#? A: <p>You can use <a href="https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/statements/iteration-statements" rel="nofollow noreferrer"><strong><code>foreach</code></strong></a> to iterate over elements in a <code>List</code> or similar container.</p>
<p>So if you have a <code>List&lt;MyButton&gt; buttons</code> you can iterate over the <code>MyButton</code>s with:</p>
<pre><code>foreach (var button in buttons) 
{
   // do what you need with the current element `button`
}
</code></pre>
<p>E.g. to find how many elements match a given name (assuming the property is <code>Name</code>) you can use:</p>
<pre><code>string nameToFind = &quot;specific_name&quot;;  // initialize from the user prompt
int matchingNameCount = 0;
foreach (var button in buttons)
{
    if (button.Name == nameToFind) 
    {  
        matchingNameCount++; 
    }
}
// here `matchingNameCount` will hold the number of elements with a matching name.
</code></pre>
<p>You can use it similarly to find out the minimum area elements etc.</p>

Q: Is it possible to write a Swift function that replaces only part of an extended grapheme cluster? A: <p>Using the <a href="https://developer.apple.com/reference/swift/string/1642786-range" rel="noreferrer"><code>range(of:options:range:locale:)</code></a> the solution became quite concise:</p>

<pre><code>extension String {
    func replaceFirstOccurrence(of searchString: String, with replacementString: String) -&gt; String {
        guard let range = self.range(of: searchString, options: .literal) else { return self }
        return self.replacingCharacters(in: range, with: replacementString)
    }
}
</code></pre>

<p>This works by first finding the range of <code>searchString</code> within the instance, and if a range is found the range is replaced with <code>replacementString</code>. Otherwise the instance just returns itself. And, since the <code>range(of:)</code> method returns as soon as it finds a match, the returned range is guaranteed to be the first occurrence.</p>

<pre><code>"221".replaceFirstOccurrence(of: "2", with: "3")                // 321
"👩‍👩‍👧‍👦".replaceFirstOccurrence(of: "\u{1f469}", with: "\u{1f468}") // 👨‍👩‍👧‍👦
</code></pre>

<p><sup>*To clarify, the last test case converts <em>woman-woman-girl-boy</em> to <em>man-woman-girl-boy</em>.</sup></p>

Q: Google Assistant Input to Python Output A: <pre><code>const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, Footer, AlignmentType, PageOrientation, HeadingLevel,
  BorderStyle, WidthType, ShadingType, VerticalAlign, SimpleField,
  TabStopType, TabStopPosition, LevelFormat, PageBreak, ImageRun
} = require('docx');
const fs = require('fs');

// ── Palette ──────────────────────────────────────────────────────────────────
const C = {
  navy:       &quot;1B3A6B&quot;,
  blue:       &quot;2563A8&quot;,
  blueLight:  &quot;D6E4F4&quot;,
  blueMid:    &quot;4A90C4&quot;,
  teal:       &quot;006B6B&quot;,
  tealLight:  &quot;D0EEEE&quot;,
  amber:      &quot;B45309&quot;,
  amberLight: &quot;FEF3C7&quot;,
  red:        &quot;B91C1C&quot;,
  redLight:   &quot;FEE2E2&quot;,
  gray:       &quot;F3F4F6&quot;,
  grayMid:    &quot;E5E7EB&quot;,
  white:      &quot;FFFFFF&quot;,
  black:      &quot;111111&quot;,
  text:       &quot;1F2937&quot;,
};

const bSingle = (color=&quot;AAAAAA&quot;, sz=4) =&gt; ({ style: BorderStyle.SINGLE, size: sz, color });
const bNone   = ()                      =&gt; ({ style: BorderStyle.NONE,   size: 0, color: &quot;FFFFFF&quot; });
const allBorders = (c=&quot;AAAAAA&quot;,sz=4)   =&gt; ({ top:bSingle(c,sz), bottom:bSingle(c,sz), left:bSingle(c,sz), right:bSingle(c,sz) });
const noBorders  = ()                   =&gt; ({ top:bNone(), bottom:bNone(), left:bNone(), right:bNone() });

const run  = (text,opts={}) =&gt; new TextRun({ text, font:&quot;Arial&quot;, size:18, color:C.text, ...opts });
const bold = (text,opts={}) =&gt; run(text, { bold:true, ...opts });
const sp   = ()             =&gt; new Paragraph({ spacing:{before:0,after:0}, children:[run(&quot;&quot;)] });

function cell(children, w, opts={}) {
  const { fill=C.white, borders=allBorders(), valign=VerticalAlign.CENTER,
          margins={top:60,bottom:60,left:100,right:100}, span } = opts;
  const cfg = {
    borders, width:{size:w,type:WidthType.DXA},
    shading:{fill,type:ShadingType.CLEAR},
    margins, verticalAlign:valign,
    children: Array.isArray(children)?children:[children],
  };
  if (span) cfg.columnSpan = span;
  return new TableCell(cfg);
}

function hCell(text,w,opts={}) {
  return cell(
    new Paragraph({alignment:opts.align||AlignmentType.CENTER, children:[bold(text,{color:C.white,size:opts.size||17})]}),
    w, { fill:opts.fill||C.navy, borders:allBorders(C.navy,6), ...opts }
  );
}

function labelCell(text,w,opts={}) {
  return cell(new Paragraph({children:[bold(text,{color:C.navy,size:17})]}), w,
    {fill:opts.fill||C.blueLight, borders:allBorders(&quot;AAAAAA&quot;), ...opts});
}

function sectionBanner(title, subtitle=&quot;&quot;, fill=C.navy) {
  const children=[bold(title,{color:C.white,size:20,allCaps:true})];
  if(subtitle){ children.push(run(&quot;  |  &quot;,{color:C.blueMid,size:17})); children.push(run(subtitle,{color:&quot;#CCDDFF&quot;,size:17,italics:true})); }
  return new Table({
    width:{size:13680,type:WidthType.DXA}, columnWidths:[13680],
    rows:[new TableRow({children:[
      cell(new Paragraph({children}), 13680, {
        fill, borders:{top:bSingle(fill),bottom:bSingle(C.blueMid,8),left:bSingle(fill),right:bSingle(fill)},
        margins:{top:100,bottom:100,left:160,right:160}
      })
    ]})]
  });
}

// ── Patient demographics ──────────────────────────────────────────────────────
function demographicsTable() {
  const c6=[2280,2280,2280,2280,2280,2280];
  return new Table({
    width:{size:13680,type:WidthType.DXA}, columnWidths:c6,
    rows:[
      new TableRow({children:[hCell(&quot;PATIENT DETAILS&quot;,13680,{fill:C.navy,span:6})]}),
      new TableRow({children:[
        labelCell(&quot;Full Name&quot;,c6[0]),
        cell(new Paragraph({children:[run(&quot;______________________________&quot;,{size:17})]}),c6[1]+c6[2],{fill:C.white,borders:allBorders(&quot;AAAAAA&quot;),span:2}),
        labelCell(&quot;MRN / Hospital ID&quot;,c6[3]),
        cell(new Paragraph({children:[run(&quot;____________________&quot;,{size:17})]}),c6[4]+c6[5],{fill:C.white,borders:allBorders(&quot;AAAAAA&quot;),span:2}),
      ]}),
      new TableRow({children:[
        labelCell(&quot;Date of Birth&quot;,c6[0]),
        cell(new Paragraph({children:[run(&quot;___/___/______&quot;,{size:17})]}),c6[1],{fill:C.white,borders:allBorders(&quot;AAAAAA&quot;)}),
        labelCell(&quot;Age&quot;,c6[2]),
        cell(new Paragraph({children:[run(&quot;_____ yrs&quot;,{size:17})]}),c6[3],{fill:C.white,borders:allBorders(&quot;AAAAAA&quot;)}),
        labelCell(&quot;Sex&quot;,c6[4]),
        cell(new Paragraph({children:[run(&quot;\u25A1 M   \u25A1 F   \u25A1 Other&quot;,{size:17})]}),c6[5],{fill:C.white,borders:allBorders(&quot;AAAAAA&quot;)}),
      ]}),
      new TableRow({children:[
        labelCell(&quot;Weight (kg)&quot;,c6[0]),
        cell(new Paragraph({children:[run(&quot;_________ kg&quot;,{size:17})]}),c6[1],{fill:C.white,borders:allBorders(&quot;AAAAAA&quot;)}),
        labelCell(&quot;Height (cm)&quot;,c6[2]),
        cell(new Paragraph({children:[run(&quot;_________ cm&quot;,{size:17})]}),c6[3],{fill:C.white,borders:allBorders(&quot;AAAAAA&quot;)}),
        labelCell(&quot;BMI&quot;,c6[4]),
        cell(new Paragraph({children:[run(&quot;_________ kg/m\u00B2&quot;,{size:17})]}),c6[5],{fill:C.white,borders:allBorders(&quot;AAAAAA&quot;)}),
      ]}),
      new TableRow({children:[
        labelCell(&quot;Allergies&quot;,c6[0]),
        cell(new Paragraph({children:[run(&quot;\u25A1 NKDA   Other: _____________________________&quot;,{size:17})]}),c6[1]+c6[2]+c6[3],{fill:C.redLight,borders:allBorders(C.red,6),span:4}),
        labelCell(&quot;Blood Group&quot;,c6[4]),
        cell(new Paragraph({children:[run(&quot;_______  Rh: \u25A1+ \u25A1\u2013&quot;,{size:17})]}),c6[5],{fill:C.white,borders:allBorders(&quot;AAAAAA&quot;)}),
      ]}),
      new TableRow({children:[
        labelCell(&quot;Diagnosis / Procedure&quot;,c6[0]),
        cell(new Paragraph({children:[run(&quot;_____________________________________________________________&quot;,{size:17})]}),c6[1]+c6[2]+c6[3]+c6[4]+c6[5],{fill:C.white,borders:allBorders(&quot;AAAAAA&quot;),span:5}),
      ]}),
      new TableRow({children:[
        labelCell(&quot;Surgeon&quot;,c6[0]),
        cell(new Paragraph({children:[run(&quot;_________________________&quot;,{size:17})]}),c6[1]+c6[2],{fill:C.white,borders:allBorders(&quot;AAAAAA&quot;),span:2}),
        labelCell(&quot;Operating Theatre&quot;,c6[3]),
        cell(new Paragraph({children:[run(&quot;_________________________&quot;,{size:17})]}),c6[4]+c6[5],{fill:C.white,borders:allBorders(&quot;AAAAAA&quot;),span:2}),
      ]}),
    ]
  });
}

// ── Pre-op assessment ─────────────────────────────────────────────────────────
function preopTable() {
  const c4=[2500,1340,2500,7340];
  return new Table({
    width:{size:13680,type:WidthType.DXA}, columnWidths:c4,
    rows:[
      new TableRow({children:[hCell(&quot;PRE-OPERATIVE ASSESSMENT SUMMARY  (JCI AOP.1 / ASC.5)&quot;,13680,{fill:C.navy,span:4})]}),
      ...[
        [&quot;ASA Physical Status&quot;,&quot;\u25A1 I   \u25A1 II   \u25A1 III   \u25A1 IV   \u25A1 V   \u25A1 VI&quot;,&quot;Fasting Status&quot;,&quot;Solids: ___h   Liquids: ___h   \u25A1 Adequate \u25A1 Emergency&quot;],
        [&quot;Informed Consent&quot;,&quot;\u25A1 Signed   \u25A1 Verbal   \u25A1 Emergency waiver&quot;,&quot;Type of Anaesthesia&quot;,&quot;\u25A1 GA   \u25A1 Regional   \u25A1 Combined   \u25A1 MAC/Sedation&quot;],
        [&quot;Pre-op BP (mmHg)&quot;,&quot;___ / ___&quot;,&quot;Pre-op SpO2 (%)&quot;,&quot;___ % (room air)&quot;],
        [&quot;Pre-op HR (bpm)&quot;,&quot;___&quot;,&quot;Pre-op Temp (°C)&quot;,&quot;___°C&quot;],
        [&quot;Pre-op Hb (g/dL)&quot;,&quot;___&quot;,&quot;Pre-op INR&quot;,&quot;___&quot;],
        [&quot;Co-morbidities&quot;,&quot;\u25A1 HTN  \u25A1 DM  \u25A1 IHD  \u25A1 CHF  \u25A1 COPD  \u25A1 CKD  \u25A1 OSA  \u25A1 Anticoag  \u25A1 Other: ___&quot;,&quot;Pregnancy Status&quot;,&quot;\u25A1 N/A  \u25A1 Not pregnant  \u25A1 Pregnant (___wks)&quot;],
      ].map((r,ri)=&gt;new TableRow({children:[
        cell(new Paragraph({children:[bold(r[0],{size:16,color:C.navy})]}),c4[0],{fill:ri%2===0?C.blueLight:C.gray,borders:allBorders(&quot;AAAAAA&quot;)}),
        cell(new Paragraph({children:[run(r[1],{size:17})]}),c4[1],{fill:ri%2===0?C.white:C.gray,borders:allBorders(&quot;AAAAAA&quot;)}),
        cell(new Paragraph({children:[bold(r[2],{size:16,color:C.navy})]}),c4[2],{fill:ri%2===0?C.blueLight:C.gray,borders:allBorders(&quot;AAAAAA&quot;)}),
        cell(new Paragraph({children:[run(r[3],{size:17})]}),c4[3],{fill:ri%2===0?C.white:C.gray,borders:allBorders(&quot;AAAAAA&quot;)}),
      ]}))
    ]
  });
}

// ── Timing ────────────────────────────────────────────────────────────────────
function timingTable() {
  const c6=[2280,2280,2280,2280,2280,2280];
  const items=[&quot;Anaesthetic Start&quot;,&quot;Patient into OT&quot;,&quot;Induction Start&quot;,&quot;Incision Time&quot;,&quot;Wound Closure&quot;,&quot;Anaesthetic End&quot;];
  return new Table({
    width:{size:13680,type:WidthType.DXA}, columnWidths:c6,
    rows:[
      new TableRow({children:[hCell(&quot;OPERATIVE TIMING  (JCI MOI.1 / ASC.3)&quot;,13680,{fill:C.navy,span:6})]}),
      new TableRow({children:items.map((item,i)=&gt;
        cell([
          new Paragraph({alignment:AlignmentType.CENTER,children:[bold(item,{size:16,color:C.navy})]}),
          new Paragraph({alignment:AlignmentType.CENTER,children:[run(&quot;_______&quot;,{size:18})]}),
          new Paragraph({alignment:AlignmentType.CENTER,children:[run(&quot;hh : mm&quot;,{size:14,italics:true,color:&quot;888888&quot;})]}),
        ],c6[i],{fill:i%2===0?C.blueLight:C.gray,borders:allBorders(C.blue,6)})
      )}),
      new TableRow({children:[
        cell(new Paragraph({children:[bold(&quot;Total Anaesthetic Duration: &quot;,{size:16,color:C.navy}),run(&quot;_________ min&quot;,{size:17})]}),6840,{fill:C.blueLight,borders:allBorders(C.blue,6),span:3}),
        cell(new Paragraph({children:[bold(&quot;Total Surgical Duration: &quot;,{size:16,color:C.navy}),run(&quot;_________ min&quot;,{size:17})]}),6840,{fill:C.blueLight,borders:allBorders(C.blue,6),span:3}),
      ]}),
    ]
  });
}

// ── Equipment checklist ───────────────────────────────────────────────────────
function checklistTable() {
  const col2=[6840,6840];
  const items1=[&quot;Anaesthetic machine checked &amp; signed&quot;,&quot;Vaporiser(s) filled and calibrated&quot;,&quot;Circle system tested – no leaks&quot;,&quot;Soda lime colour – adequate&quot;,&quot;Breathing circuit integrity confirmed&quot;,&quot;Flowmeter function verified&quot;,&quot;Oxygen analyser calibrated&quot;,&quot;Capnograph connected &amp; zeroed&quot;,&quot;Pulse oximeter – functioning&quot;,&quot;NIBP cuff – correct size applied&quot;,&quot;ECG leads – 5-lead attached&quot;,&quot;Temperature probe positioned&quot;,&quot;BIS / depth monitor connected&quot;,&quot;Nerve stimulator available (if NMBA used)&quot;];
  const items2=[&quot;IV access – patent, flushed&quot;,&quot;Suction – tested at bedside&quot;,&quot;Difficult airway trolley available&quot;,&quot;Video laryngoscope charged/ready&quot;,&quot;Defibrillator / AED confirmed available&quot;,&quot;Warming device activated&quot;,&quot;DVT prophylaxis – stockings / pneumatic&quot;,&quot;Eye protection applied&quot;,&quot;Patient positioning padded &amp; documented&quot;,&quot;Surgical time-out completed (WHO checklist)&quot;,&quot;Fire safety precautions in place&quot;,&quot;Allergies re-confirmed with team&quot;,&quot;Blood products – consent &amp; availability confirmed&quot;,&quot;Emergency drugs drawn / labelled&quot;];
  return new Table({
    width:{size:13680,type:WidthType.DXA}, columnWidths:col2,
    rows:[
      new TableRow({children:[hCell(&quot;PRE-OPERATIVE EQUIPMENT &amp; SAFETY CHECKS (JCI ASC.7.2 / ASC.7.3)&quot;,13680,{fill:C.navy,span:2})]}),
      new TableRow({children:[hCell(&quot;Machine &amp; Monitoring&quot;,col2[0],{fill:C.blue}),hCell(&quot;Safety &amp; Environment&quot;,col2[1],{fill:C.blue})]}),
      ...items1.map((a,i)=&gt;new TableRow({children:[
        cell(new Paragraph({children:[run(&quot;\u25A1  &quot;,{bold:true,color:C.blue}),run(a,{size:17})]}),col2[0],{fill:C.white,borders:allBorders(&quot;BBBBBB&quot;,3)}),
        cell(new Paragraph({children:[run(&quot;\u25A1  &quot;,{bold:true,color:C.blue}),run(items2[i],{size:17})]}),col2[1],{fill:C.white,borders:allBorders(&quot;BBBBBB&quot;,3)}),
      ]})),
      new TableRow({children:[
        cell(new Paragraph({children:[bold(&quot;Checked By: &quot;,{size:16,color:C.navy}),run(&quot;_________________________   Time: _________&quot;,{size:16})]}),13680,{fill:C.blueLight,borders:allBorders(C.blue,6),span:2})
      ]})
    ]
  });
}

// ── Airway ────────────────────────────────────────────────────────────────────
function airwayTable() {
  const cols3=[2800,5240,5640];
  function row3(a,b,c,fillA=C.blueLight,fillB=C.white){
    return new TableRow({children:[
      cell(new Paragraph({children:[bold(a,{size:17,color:C.navy})]}),cols3[0],{fill:fillA,borders:allBorders(&quot;AAAAAA&quot;)}),
      cell(new Paragraph({children:[run(b,{size:17})]}),cols3[1],{fill:fillB,borders:allBorders(&quot;AAAAAA&quot;)}),
      cell(new Paragraph({children:[run(c,{size:17})]}),cols3[2],{fill:fillB,borders:allBorders(&quot;AAAAAA&quot;)}),
    ]});
  }
  return new Table({
    width:{size:13680,type:WidthType.DXA}, columnWidths:cols3,
    rows:[
      new TableRow({children:[hCell(&quot;Airway Parameter&quot;,cols3[0],{fill:C.navy}),hCell(&quot;Findings / Selection&quot;,cols3[1],{fill:C.navy}),hCell(&quot;Comments&quot;,cols3[2],{fill:C.navy})]}),
      row3(&quot;Airway Assessment&quot;,&quot;Mallampati Class: __   Mouth opening: __ cm   TMD: __ cm&quot;,&quot;Difficult airway predicted:  \u25A1 Yes  \u25A1 No&quot;),
      row3(&quot;Intubation Method&quot;,&quot;\u25A1 Direct laryngoscopy  \u25A1 Video laryngoscopy  \u25A1 Fibreoptic  \u25A1 Supraglottic (LMA/iGel)  \u25A1 Awake intubation&quot;,&quot;Blade type/size: ___________&quot;,C.blueLight,C.gray),
      row3(&quot;ETT / Device&quot;,&quot;Size: ___  Cuffed: \u25A1 Yes \u25A1 No   Insertion depth: ___ cm at lip&quot;,&quot;Cuff pressure: ___ cmH2O&quot;),
      row3(&quot;Intubation Attempt #&quot;,&quot;\u25A1 1st  \u25A1 2nd  \u25A1 3rd  \u25A1 &gt;3 (escalate/document below)&quot;,&quot;BURP / Stylet used: \u25A1 Yes \u25A1 No&quot;,C.blueLight,C.gray),
      row3(&quot;ETT Confirmation&quot;,&quot;Bilateral chest rise: \u25A1  EtCO2 waveform: \u25A1  Auscultation: \u25A1&quot;,&quot;&quot;),
      row3(&quot;Positioning&quot;,&quot;\u25A1 Supine  \u25A1 Prone  \u25A1 Lateral  \u25A1 Lithotomy  \u25A1 Trendelenburg  \u25A1 Sitting  \u25A1 Other: ________&quot;,&quot;Pressure area protection: \u25A1 Applied&quot;),
      row3(&quot;Eye Care&quot;,&quot;\u25A1 Pads applied  \u25A1 Lubricant instilled  \u25A1 Not required&quot;,&quot;&quot;,C.blueLight,C.gray),
    ]
  });
}

// ── Induction / Maintenance ───────────────────────────────────────────────────
function inductionTable() {
  const cols4=[2200,2600,4540,4340];
  const rows=[
    [&quot;Induction&quot;,&quot;________________&quot;,&quot;________________&quot;,&quot;IV \u25A1  IM \u25A1  Inhalational \u25A1  IV+inhal \u25A1&quot;],
    [&quot;Maintenance&quot;,&quot;________________&quot;,&quot;MAC target: ___  TIVA rate: ___&quot;,&quot;&quot;],
    [&quot;Muscle Relaxant&quot;,&quot;________________&quot;,&quot;Dose: ___   Reversal given: \u25A1 Yes \u25A1 No&quot;,&quot;Sugammadex / Neostigmine dose: ___&quot;],
    [&quot;Opioid&quot;,&quot;________________&quot;,&quot;Dose: ___   Route: ___&quot;,&quot;Intra-op total: ___&quot;],
    [&quot;Regional Block&quot;,&quot;________________&quot;,&quot;Volume: ___  mL  LA: ___&quot;,&quot;Level confirmed: \u25A1 Yes \u25A1 No&quot;],
    [&quot;Airway gases&quot;,&quot;O2: ___ %   N2O: ___ %   Air: ___ %&quot;,&quot;Agent: ___  End-tidal target: ___&quot;,&quot;FGF: ___ L/min&quot;],
  ];
  return new Table({
    width:{size:13680,type:WidthType.DXA}, columnWidths:cols4,
    rows:[
      new TableRow({children:[&quot;Technique&quot;,&quot;Agent(s)&quot;,&quot;Dose / Concentration&quot;,&quot;Notes&quot;].map((h,i)=&gt;hCell(h,cols4[i],{fill:C.blue}))}),
      ...rows.map((r,ri)=&gt;new TableRow({children:r.map((txt,ci)=&gt;cell(new Paragraph({children:[run(txt,{size:17})]}),cols4[ci],{fill:ri%2===0?C.white:C.gray,borders:allBorders(&quot;AAAAAA&quot;)}))}))
    ]
  });
}

// ── Drug / Fluid log ──────────────────────────────────────────────────────────
function drugTable() {
  const cols=[1200,2400,1200,1200,1200,2000,1200,3280];
  const heads=[&quot;Time&quot;,&quot;Drug / Fluid&quot;,&quot;Dose&quot;,&quot;Route&quot;,&quot;Rate&quot;,&quot;Indication&quot;,&quot;Given By&quot;,&quot;Notes&quot;];
  return new Table({
    width:{size:13680,type:WidthType.DXA}, columnWidths:cols,
    rows:[
      new TableRow({children:heads.map((h,i)=&gt;hCell(h,cols[i],{fill:C.teal}))}),
      ...Array.from({length:12},(_,r)=&gt;new TableRow({children:cols.map((w)=&gt;cell(new Paragraph({children:[run(&quot;&quot;)]}),w,{fill:r%2===0?C.white:C.tealLight,borders:allBorders(&quot;AAAAAA&quot;,3)}))}))
    ]
  });
}

// ── Fluid balance ─────────────────────────────────────────────────────────────
function fluidTable() {
  const W=13680;
  const iCols=[2000,2000,2000,2000,2000,1680];
  const oColW=[2280,2280,2280,6840];
  return new Table({
    width:{size:W,type:WidthType.DXA}, columnWidths:[W],
    rows:[
      new TableRow({children:[cell(new Paragraph({children:[bold(&quot;INPUTS&quot;,{color:C.white,size:18,allCaps:true})]}),W,{fill:C.teal,borders:allBorders(C.teal,6)})]}),
      new TableRow({children:[cell([new Table({width:{size:W,type:WidthType.DXA},columnWidths:iCols,rows:[
        new TableRow({children:[&quot;Crystalloid (mL)&quot;,&quot;Colloid (mL)&quot;,&quot;Blood / PRBC (mL)&quot;,&quot;FFP (mL)&quot;,&quot;Platelets (mL)&quot;,&quot;Other (mL)&quot;].map((h,i)=&gt;cell(new Paragraph({alignment:AlignmentType.CENTER,children:[bold(h,{size:15,color:C.navy})]}),iCols[i],{fill:C.blueLight,borders:allBorders(&quot;AAAAAA&quot;)}))}),
        new TableRow({children:iCols.map(w=&gt;cell(new Paragraph({children:[run(&quot;&quot;)]}),w,{fill:C.white,borders:allBorders(&quot;AAAAAA&quot;,3)}))}),
      ]})],W,{fill:C.white,borders:noBorders(),margins:{top:0,bottom:0,left:0,right:0}})]}),
